      dialog = 3,
      music = "406_BQ_Weddingdress",
      renwu = "npc",
      sentence = "I was weary of acting like a polite, dignified rich girl, weary of playing the bon vivant living only for today, weary of trying to be who I was \"supposed\" to be.",
